-- 0013_add_work_visit — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- visit: the same-day internal record of a site visit (SOP-DEL-03 §5.1, E5 AC3), in the field order of the
-- DingTalk Action Record template; the minutes stay in DingTalk and are linked. Staff see all rows; a client
-- sees its own rows marked visibility = 'client'; partners see nothing until a policy links their jobs.
CREATE TABLE visit (
  id             uuid PRIMARY KEY,
  client_id      uuid NOT NULL,
  site_id        uuid NOT NULL,
  -- SOP-DEL-03 §2: the type decides the folder.
  type           text NOT NULL CHECK (type IN
                   ('site_survey', 'technical_inspection', 'installation', 'commissioning', 'maintenance')),
  visit_date     date NOT NULL,
  -- [{ name, side: vv | client | third_party }] — everyone present (§5.1 Attendees).
  attendees      jsonb NOT NULL CHECK (jsonb_typeof(attendees) = 'array' AND jsonb_array_length(attendees) >= 1),
  summary        text NOT NULL CHECK (btrim(summary) <> ''),
  -- §4 "Separate agreed from discussed": [{ text, agreedWith }] names, not "the client"; discussed: [text].
  decided        jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(decided) = 'array'),
  discussed      jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(discussed) = 'array'),
  key_points     text,
  -- §5.1 Key Points: "state coverage explicitly: X of Y", and why the rest was not covered.
  coverage_done  integer NOT NULL CHECK (coverage_done >= 0),
  coverage_total integer NOT NULL CHECK (coverage_total >= 1),
  coverage_gap   text,
  follow_up      text,
  escalate       boolean NOT NULL DEFAULT false,
  -- Link to the DingTalk Action Record minutes (§5.1); filed per SOP-DEL-02.
  minutes_ref    text,
  -- §5.2 formal Site Visit Report: SVR-NN, a running number per project, when one is written.
  svr_no         integer CHECK (svr_no BETWEEN 1 AND 99),
  visibility     text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  recorded_by    uuid NOT NULL,
  recorded_at    timestamptz NOT NULL DEFAULT now(),
  archived_at    timestamptz,
  UNIQUE (id, client_id),
  UNIQUE (site_id, svr_no),
  CONSTRAINT visit_coverage CHECK (coverage_done <= coverage_total),
  CONSTRAINT visit_gap_explained CHECK (coverage_done = coverage_total OR coalesce(btrim(coverage_gap), '') <> ''),
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX visit_site ON visit (site_id, visit_date);
CREATE INDEX visit_client ON visit (client_id);

-- Action items spoken in the record (§5.1 Key Action Items) link to their visit; source is then 'visit'.
ALTER TABLE action ADD COLUMN visit_id uuid;
ALTER TABLE action ADD CONSTRAINT action_visit FOREIGN KEY (visit_id, client_id) REFERENCES visit (id, client_id);
ALTER TABLE action ADD CONSTRAINT action_visit_source CHECK (visit_id IS NULL OR source_kind = 'visit');

ALTER TABLE visit ENABLE ROW LEVEL SECURITY;
CREATE POLICY visit_internal ON visit FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY visit_client_read ON visit FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON visit TO ocs_app;
